void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    float t = uv.x;                       // deliberately ignores iTime
    vec3 col = vec3(0.15 + 0.85 * t, 0.06 * t, 0.05 * t);
    fragColor = vec4(col, 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    float r = length(uv);
    // Pulse radius breathes with time; brightest at centre, dark at corners.
    float pulse = 0.55 + 0.30 * sin(iTime * 2.2);
    float falloff = smoothstep(pulse, 0.0, r);
    float core = exp(-r * r * 7.0);
    float i = clamp(falloff * 0.75 + core * 0.85, 0.0, 1.0);
    vec3 col = vec3(0.12, 0.30, 1.0) * i;
    col += vec3(0.05, 0.10, 0.28) * (1.0 - r);
    fragColor = vec4(col, 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    vec2 c = floor(uv * 8.0);
    float check = mod(c.x + c.y, 2.0);
    vec3 col = mix(vec3(0.02, 0.03, 0.02), vec3(0.15, 0.95, 0.25), check);
    fragColor = vec4(col, 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / min(iResolution.x, iResolution.y);
    float d = length(uv) - 0.30;            // signed distance to the circle
    float inside = step(d, 0.0);            // hard edge, no smoothstep
    vec3 col = mix(vec3(0.02), vec3(1.0, 0.55, 0.08), inside);
    fragColor = vec4(col, 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    float r = length(uv);
    float a = atan(uv.y, uv.x) + iTime * 0.6;
    float petals = 0.5 + 0.5 * cos(a * 6.0);          // 6-fold
    float shape = smoothstep(0.42 * (0.45 + 0.55 * petals), 0.0, r);
    float i = clamp(shape + exp(-r * r * 9.0) * 0.6, 0.0, 1.0);
    fragColor = vec4(vec3(0.08, 0.75, 1.0) * i, 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    float brightness = smoothstep(0.0, 1.0, uv.x);
    vec3 color = vec3(1.0, 0.0, 0.0) * brightness;
    fragColor = vec4(color, 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;
    float d = length(uv);
    float pulse = smoothstep(0.8, 0.9, d);
    float animation = sin(iTime * 5.0) * 0.5 + 0.5;
    float intensity = pulse * animation;
    fragColor = vec4(0.0, 0.0, 1.0, 1.0) * intensity + vec4(0.0, 0.0, 0.1, 1.0) * (1.0 - intensity);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy;
    uv *= 8.0;
    vec2 id = floor(uv);
    float pattern = mod(id.x + id.y, 2.0);
    fragColor = pattern < 0.5 ? vec4(0.0, 0.0, 0.0, 1.0) : vec4(0.0, 1.0, 0.0, 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy;
    uv = uv * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    float radius = 0.3 * min(iResolution.x, iResolution.y) / iResolution.x;
    float dist = length(uv) - radius;

    vec3 color = vec3(0.0);
    if (dist <= 0.0) {
        color = vec3(1.0, 0.5, 0.0); // Bright orange
    }

    fragColor = vec4(color, 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - iResolution.xy * 0.5) / iResolution.y;
    float angle = atan(uv.y, uv.x) + iTime * 0.1;
    float radius = length(uv);
    float symmetry = 6.0 * fract(angle / (2.0 * 3.14159265359));
    float brightness = 1.0 - smoothstep(0.2, 0.5, radius);
    vec3 color = vec3(0.0, 1.0, 1.0) * brightness * (1.0 - abs(sin(symmetry * 3.14159265359 * 2.0)));
    fragColor = vec4(color, 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    float brightness = uv.x;
    fragColor = vec4(1.0, 0.0, 0.0, 1.0) * brightness;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy;
    uv -= 0.5;
    uv /= 0.5;

    float dist = length(uv);
    float pulse = smoothstep(0.8, 0.0, dist - sin(iTime) * 0.2);

    vec3 color = vec3(0.0, 0.0, 1.0) * pulse;
    color += vec3(0.0, 0.0, 0.2) * (1.0 - pulse);

    fragColor = vec4(color, 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy;
    uv *= 8.0;
    vec2 grid = floor(uv);
    float checker = mod(grid.x + grid.y, 2.0);
    fragColor = vec4(checker, 1.0 - checker, 0.0, 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy;
    uv = uv * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    float aspect = iResolution.x / iResolution.y;
    float radius = 0.3 * min(iResolution.x, iResolution.y) / iResolution.xy.y;

    float dist = length(uv) - radius;

    vec3 color = vec3(0.0);
    if (dist < 0.0) {
        color = vec3(1.0, 0.647, 0.0); // Bright orange
    }

    fragColor = vec4(color, 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - iResolution.xy * 0.5) / iResolution.y;
    float angle = atan(uv.y, uv.x);
    float radius = length(uv);
    float symmetry = 6.0;
    float pattern = abs(sin(angle * symmetry + iTime * 0.1)) + abs(cos(angle * symmetry + iTime * 0.1));
    float brightness = smoothstep(1.0, 0.0, radius);
    fragColor = vec4(0.0, 1.0, 1.0, 1.0) * pattern * brightness;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    float brightness = uv.x;
    fragColor = vec4(brightness, 0.0, 0.0, 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    float d = length(uv);
    float pulse = smoothstep(0.0, 0.5, 0.5 - abs(d - 0.5 * sin(iTime)));
    vec3 color = mix(vec3(0.0, 0.0, 1.0), vec3(0.0, 0.0, 0.0), pulse);
    fragColor = vec4(color, 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy;
    vec2 gridUv = uv * 8.0;
    vec2 gridFrac = fract(gridUv);
    vec3 color = vec3(0.0, 1.0, 0.0); // Bright green
    if (mod(gridUv.x, 2.0) > 1.0) {
        color = vec3(0.0, 0.0, 0.0); // Near-black
    }
    if (mod(gridUv.y, 2.0) > 1.0) {
        color = mix(color, vec3(0.0, 0.0, 0.0), 1.0);
    }
    fragColor = vec4(color, 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    float aspect = iResolution.x / iResolution.y;
    uv.x *= aspect;
    float radius = 0.3 * min(iResolution.x, iResolution.y) / iResolution.y;
    float d = length(uv) - radius;
    fragColor = d < 0.0 ? vec4(1.0, 0.5, 0.0, 1.0) : vec4(0.0, 0.0, 0.0, 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - iResolution.xy * 0.5) / iResolution.y;
    float r = length(uv);
    float theta = atan(uv.y, uv.x) + iTime * 0.1;
    float angle = mod(theta, 2.0 * 3.141592653589793 / 3.0);
    float pattern = abs(cos(angle * 3.0)) + abs(sin(angle * 3.0));
    float brightness = 1.0 - smoothstep(0.3, 0.5, r);
    fragColor = vec4(0.0, 1.0, 1.0, 1.0) * pattern * brightness;
}
